  { cat: 'instruction_override', re: /\b(system prompt|you are now|new instructions?\s*:|act as an?|developer mode|jailbreak)\b/i },
  { cat: 'data_exfiltration', re: /\b(reveal|show|print|list|dump|export|output|display|share|disclose|send)\b[^.]{0,50}\b(salar(y|ies)|pay ?bands?|compensation|employee (records?|names?|ids?|details|data)|all employees?|personal data|performance ratings?)\b/i },
