const ctx = $input.first().json;
const BATCH_SIZE = 20;
const MAX_REVIEW_RECORDS = 300;
const TOP_RISK_RECORDS = 40;
const RELEVANT = ['Month','Department','Cost_Category','Project','Cost_Centre','Budget_INR','Actual_INR','Evidence_Status','Business_Context','Notes_Untrusted_Source_Text'];
const PROXY = ['Age_Band','Gender','Region','Education_Level','Tenure_Band'];
const SENSITIVE = ['Salary_Band','Performance_Rating'];
function norm(v) { if (v === null || v === undefined) return ''; if (typeof v === 'number') return String(v); const s = String(v).trim(); return /^-?\d+(\.\d+)?$/.test(s.replace(/,/g, '')) ? String(parseFloat(s.replace(/,/g, ''))) : s.toLowerCase(); }

const groups = {};
(ctx.records || []).forEach(r => {
  const pid = r.Counterfactual_Pair_ID === null || r.Counterfactual_Pair_ID === undefined ? '' : String(r.Counterfactual_Pair_ID).trim();
