// Node 8 (part 2) - Deterministic fairness and counterfactual comparison. Does not rely on the AI to judge itself.
const ctx = $('Classify Evidence').first().json;
const batchItems = $('Validate Pairs & Batch Records').all().map(i => i.json);
const pairsInfo = batchItems[0].fairness_pairs;
const RISK = ['High', 'Medium', 'Low'];
const ACTIONS = ['Escalate for human review', 'Monitor', 'No action required'];
const outputs = $input.all();
const reviews = {}; const batchFailures = []; const hallucinatedIds = []; const enumViolations = [];
let evidenceOverrides = 0; const evidenceOverrideIds = [];
const minMap = {};
(ctx.minimised_records || []).forEach(m => { minMap[m.Record_ID] = m; });
outputs.forEach((it, idx) => {
  const j = it.json || {};
  const expected = (batchItems[idx] && batchItems[idx].record_ids) || [];
  if (j.error || !j.output || !Array.isArray(j.output.reviews)) {
    if (expected.length) batchFailures.push({ batch_index: idx, records: expected.length, error: String(j.error || 'Missing or malformed reviews array').slice(0, 300) });
    return;
  }
  j.output.reviews.forEach(rv => {
    const id = String(rv.record_id || '').trim();
    if (!expected.includes(id)) { hallucinatedIds.push(id); return; }
    const rec = minMap[id];
    const out = { risk_classification: rv.risk_classification, recommended_action: rv.recommended_action, evidence_classification: rv.evidence_classification, rationale: String(rv.rationale || '').slice(0, 400) };
    if (!RISK.includes(out.risk_classification) || !ACTIONS.includes(out.recommended_action)) enumViolations.push(id);
    if (rec && rec.Evidence_Status !== 'VERIFIED' && /verified/i.test(String(out.evidence_classification)) && !/unverified|not verified/i.test(String(out.evidence_classification))) {
      evidenceOverrides++; evidenceOverrideIds.push(id);
      out.evidence_classification = rec.Evidence_Class + ' (AI label overridden by guardrail)';
    }
    reviews[id] = out;
  });
});
// Deterministic workflow risk rule - financial and evidence fields only
function wfRisk(m) {
  const p = typeof m.Variance_Percent === 'number' ? m.Variance_Percent : null;
  if (m.Evidence_Status === 'CONFLICTING') return 'High';
  if (p !== null && Math.abs(p) >= 25) return 'High';
  if (p !== null && p > 10 && (m.Evidence_Status === 'UNAVAILABLE' || m.Evidence_Status === 'PARTIAL')) return 'High';
  if (p !== null && Math.abs(p) >= 10) return 'Medium';
  return 'Low';
}
const original = {};
(ctx.records || []).forEach(r => { original[String(r.Record_ID)] = r; });
const compared = []; const aiDiffs = []; const sourceDiffs = []; const wfDiffs = []; const notCompared = [];
const byAttr = {};
pairsInfo.valid.forEach(p => {
  const ma = minMap[p.a_id], mb = minMap[p.b_id];
  const oa = original[p.a_id], ob = original[p.b_id];
  if (wfRisk(ma) !== wfRisk(mb)) wfDiffs.push({ pair_id: p.pair_id, a: wfRisk(ma), b: wfRisk(mb) });
  ['Risk_Level', 'Approval_Status'].forEach(f => {
    if (String(oa[f] || '').trim().toLowerCase() !== String(ob[f] || '').trim().toLowerCase()) sourceDiffs.push({ pair_id: p.pair_id, record_ids: [p.a_id, p.b_id], field: f, a: oa[f], b: ob[f], proxy_diffs: p.proxy_diffs });
  });
  const ra = reviews[p.a_id], rb = reviews[p.b_id];
  p.proxy_diffs.forEach(attr => { byAttr[attr] = byAttr[attr] || { pairs: 0, compared: 0, ai_differences: 0, source_differences: 0 }; byAttr[attr].pairs++; });
  if (!ra || !rb) { notCompared.push(p.pair_id); return; }
  const diffs = [];
  if (ra.risk_classification !== rb.risk_classification) diffs.push({ field: 'risk_classification', a: ra.risk_classification, b: rb.risk_classification });
  if (ra.recommended_action !== rb.recommended_action) diffs.push({ field: 'recommended_action', a: ra.recommended_action, b: rb.recommended_action });
