const fairness = {
  total_pairs: pairsInfo.total_pairs, valid_pairs: pairsInfo.valid_count, invalid_pairs: pairsInfo.invalid_count,
  invalid_pair_details: pairsInfo.invalid, valid_pair_details: pairsInfo.valid,
  pairs_compared: compared.length, pairs_not_compared: notCompared,
  ai_consistency_rate_pct: consistency, ai_unexplained_differences: aiDiffs,
  source_data_disparities: sourceDiffs, workflow_rule_differences: wfDiffs, by_proxy_attribute: byAttr,
  reviewer: { review_set_size: batchItems[0].review_set_size, reviews_received: Object.keys(reviews).length, batch_failures: batchFailures, hallucinated_ids: hallucinatedIds, enum_violations: enumViolations, evidence_overrides: evidenceOverrides, evidence_override_ids: evidenceOverrideIds, privacy_exposures: batchItems[0].reviewer_privacy_exposures },
