(ctx.minimised_records || []).forEach(m => { wf_risk[m.Record_ID] = wfRisk(m); });
return [{ json: Object.assign({}, ctx, { fairness, ai_reviews: reviews, wf_risk }) }];

// Build the aggregated, minimised analyst payload (no raw 1,500-record dump) and run the privacy gate.
const ctx = $input.first().json;
