const minMap = {};
(ctx.minimised_records || []).forEach(m => { minMap[m.Record_ID] = m; });
function rec(id) {
  const m = minMap[id]; if (!m) return null;
  return { record_id: m.Record_ID, department: m.Department, cost_category: m.Cost_Category, project: m.Project, cost_centre: m.Cost_Centre, month: m.Month,
    budget_inr: m.Budget_INR, actual_inr: m.Actual_INR, variance_inr: m.Variance_INR, variance_pct: m.Variance_Percent,
    dataset_risk_level: m.Risk_Level, approval_status: m.Approval_Status, evidence_status: m.Evidence_Status, explanation_class: m.Explanation_Class,
    untrusted_business_context: m.Business_Context, untrusted_notes: m.Notes_Untrusted_Source_Text };
}
