    '<h2>10. Risks and Anomalies</h2>' + para(o.risks_and_anomalies) + '<p class="muted">Deterministic signals: ' + c.counts.high_risk + ' high-risk records; ' + ctx.evidence.counts.CONFLICTING + ' conflicting evidence; ' + ctx.evidence.counts.UNAVAILABLE + ' unavailable evidence; ' + ctx.validation.duplicate_ids.length + ' duplicate IDs; ' + ctx.validation.calc_mismatch_count + ' stored-vs-recalculated mismatches; ' + ctx.injection.flagged_records + ' records with isolated untrusted text.</p>' +
    '<h2>11. Management Recommendations (advisory)</h2><ul>' + (recs || '<li class="muted">None.</li>') + '</ul>' +
