    '<h2>13. Human-Review Cases</h2><p>' + ctx.human_review_count + ' records require human review (full list saved to the "fpa_b_human_review_queue" Data Table). Largest 25 by absolute variance:</p><table><tr><th>Record</th><th>Dept</th><th>Variance</th><th>Var %</th><th>Risk reason</th><th>Evidence</th><th>AI recommendation</th></tr>' + hrRows + '</table>' + para(o.human_review_requirements) +
    '<h2>14. Conclusion</h2>' + para(o.conclusion) +
    '<p class="muted">Sensitive employee and proxy attributes were removed before AI processing. Improvements over Workflow A must not be claimed until both workflows are tested on the same inputs.</p></body></html>';
} catch (e) {
  status = 'fallback'; errs.push('Report A generation failed: ' + e.message);
  html = '<!DOCTYPE html><html><body><h1>FP&amp;A Management Report - generation failed</h1><p>' + esc(e.message) + '</p><p>Deterministic data and the testing report remain available. Please contact the workflow owner.</p></body></html>';
}
return [{ json: Object.assign({}, ctx, { report_a_html: html, report_a_status: status, errors: (ctx.errors || []).concat(errs) }) }];

// Report B - Responsible AI Testing Report + audit log record.
const ctx = $input.first().json;
function esc(s) { return String(s === null || s === undefined ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); }
const errors = (ctx.errors || []).slice();
let html = ''; let summary = {};
try {
  const tests = ctx.tests || [];
  const total = tests.length; const passed = tests.filter(t => t.status === 'Pass').length; const failed = tests.filter(t => t.status === 'Fail').length; const notRun = tests.filter(t => t.status === 'Not Run').length;
  const passPct = total ? Math.round(passed / total * 10000) / 100 : 0;
  summary = { total, passed, failed, not_run: notRun, review_cases: ctx.human_review_count || 0, pass_percentage: passPct, route: ctx.route };
  const cls = s => s === 'Pass' ? 'p' : (s === 'Fail' ? 'f' : 'n');
  const rows = tests.map(t => '<tr><td>' + esc(t.test_id) + '</td><td>' + esc(t.scenario) + '</td><td>' + esc(t.expected) + '</td><td>' + esc(t.actual) + '</td><td class="' + cls(t.status) + '">' + esc(t.status) + '</td><td>' + esc(t.severity) + '</td><td>' + esc(t.control) + '</td><td>' + esc(t.explanation) + '</td><td>' + esc(t.improvement) + '</td></tr>').join('');
  const fr = ctx.fairness || null;
  const inj = ctx.injection || null; const pv = ctx.privacy || null; const val = ctx.validation || {};
  const fairHtml = fr ? ('<p>Total pairs: ' + fr.total_pairs + ' | Valid: ' + fr.valid_pairs + ' | Invalid (excluded from scoring): ' + fr.invalid_pairs + ' | AI-compared: ' + fr.pairs_compared + ' | AI consistency: ' + (fr.ai_consistency_rate_pct === null ? 'n/a' : fr.ai_consistency_rate_pct + '%') + '</p>' +
    '<p>By proxy attribute: ' + esc(JSON.stringify(fr.by_proxy_attribute)) + '</p>' +
    '<h3>Unexplained AI differences in valid pairs</h3>' + (fr.ai_unexplained_differences.length ? '<ul>' + fr.ai_unexplained_differences.map(d => '<li>' + esc(d.pair_id) + ' (' + esc(d.record_ids.join(' vs ')) + '; proxies differ: ' + esc(d.proxy_diffs.join(', ')) + '): ' + esc(JSON.stringify(d.differences)) + '</li>').join('') + '</ul>' : '<p>None detected.</p>') +
    '<h3>Source-data disparities in valid pairs</h3>' + (fr.source_data_disparities.length ? '<ul>' + fr.source_data_disparities.slice(0, 50).map(d => '<li>' + esc(d.pair_id) + ': ' + esc(d.field) + ' ' + esc(d.a) + ' vs ' + esc(d.b) + ' (proxies differ: ' + esc(d.proxy_diffs.join(', ')) + ')</li>').join('') + '</ul>' : '<p>None detected.</p>') +
    '<h3>Invalid pairs (first 50)</h3><ul>' + fr.invalid_pair_details.slice(0, 50).map(p => '<li>' + esc(p.pair_id) + ' (' + esc(p.record_ids.join(', ')) + '): ' + esc(p.reasons.join('; ')) + '</li>').join('') + '</ul><p class="m">' + esc(fr.limitation) + '</p>') : '<p>Fairness evaluation not executed (workflow blocked earlier).</p>';
  const injHtml = inj ? ('<p>Flagged fields: ' + inj.flagged_fields + ' in ' + inj.flagged_records + ' records. By category: ' + esc(JSON.stringify(inj.by_category)) + '</p><p>Probe results: ' + inj.probes.map(p => esc(p.key) + '=' + (p.correct ? 'correct' : 'WRONG')).join(', ') + '</p><h3>Isolated original text (audit copy, first 50)</h3><table><tr><th>Record</th><th>Field</th><th>Categories</th><th>Original text (never sent to AI)</th></tr>' + inj.flags.slice(0, 50).map(f => '<tr><td>' + esc(f.record_id) + '</td><td>' + esc(f.field) + '</td><td>' + esc(f.categories.join(', ')) + '</td><td>' + esc(f.original_text) + '</td></tr>').join('') + '</table>') : '<p>Not executed.</p>';
  const pvHtml = pv ? ('<p>' + esc(pv.log) + '</p><p>Removed: ' + esc(pv.removed_fields.join(', ')) + '<br>Withheld: ' + esc(pv.withheld_fields.join(', ')) + '<br>Privacy gate: ' + (ctx.privacy_gate ? (ctx.privacy_gate.passed ? 'PASSED' : 'CLOSED - ' + esc(ctx.privacy_gate.exposures.join(', '))) : 'n/a') + '</p>') : '<p>Not executed.</p>';
  html = '<!DOCTYPE html><html><head><meta charset="utf-8"><title>Responsible AI Testing Report - Workflow B</title><style>body{font-family:Segoe UI,Arial,sans-serif;margin:28px;color:#222}h1,h2{color:#4a235a}h2{border-bottom:2px solid #4a235a;padding-bottom:3px;margin-top:28px}table{border-collapse:collapse;width:100%;font-size:12px}th{background:#4a235a;color:#fff;text-align:left;padding:5px;vertical-align:top}td{border-bottom:1px solid #ddd;padding:5px;vertical-align:top}.p{color:#1e8449;font-weight:bold}.f{color:#c0392b;font-weight:bold}.n{color:#7f8c8d;font-weight:bold}.cards{display:flex;gap:10px;flex-wrap:wrap}.c{background:#f5eef8;border-radius:6px;padding:10px 14px;min-width:120px}.c b{display:block;font-size:20px}.m{color:#666;font-size:12px}</style></head><body>' +
    '<h1>Nexora Technologies - Responsible AI Testing Report</h1><p class="m">Workflow B (with guardrails). Run ' + esc(ctx.run_id) + ', ' + new Date().toISOString() + '. Dataset: ' + esc(ctx.dataset_filename) + '. Model: ' + esc(ctx.ai_model) + '. Results are measured from this execution (real data plus controlled probes run through the same control code). Expected results are defined separately and are never sent to the AI.</p>' +
    '<div class="cards"><div class="c">Total tests<b>' + total + '</b></div><div class="c">Passed<b class="p">' + passed + '</b></div><div class="c">Failed<b class="f">' + failed + '</b></div><div class="c">Not run<b class="n">' + notRun + '</b></div><div class="c">Review cases<b>' + summary.review_cases + '</b></div><div class="c">Pass %<b>' + passPct + '%</b></div><div class="c">Final route<b>' + esc(ctx.route) + '</b></div></div>' +
    '<p>Block reasons: ' + esc((ctx.block_reasons || []).join('; ') || 'none') + '<br>Review reasons: ' + esc((ctx.review_reasons || []).join('; ') || 'none') + '</p>' +
    '<h2>Test results</h2><table><tr><th>Test ID</th><th>Scenario</th><th>Expected result</th><th>Actual result</th><th>Pass/Fail</th><th>Severity</th><th>Control applied</th><th>Explanation</th><th>Recommended improvement</th></tr>' + rows + '</table>' +
    '<h2>Data validation</h2><p>Valid: ' + val.valid + ' | Rows: ' + val.rows_extracted + ' | Missing columns: ' + esc((val.missing_columns || []).join(', ') || 'none') + ' | Missing budgets: ' + (val.missing_budget || []).length + ' | Invalid numeric: ' + (val.invalid_numeric || []).length + ' | Zero budgets: ' + (val.zero_budget || []).length + ' | Duplicate IDs: ' + (val.duplicate_ids || []).length + ' | Stored-vs-recalculated mismatches: ' + val.calc_mismatch_count + '</p>' +
    '<h2>Privacy minimisation log</h2>' + pvHtml +
    '<h2>Prompt-injection log</h2>' + injHtml +
    '<h2>Evidence classification</h2><p>' + (ctx.evidence ? esc(JSON.stringify(ctx.evidence.counts)) + '<br>' + esc(ctx.evidence.note) : 'Not executed.') + '</p>' +
    '<h2>Fairness and counterfactual testing</h2>' + fairHtml +
    '<h2>AI output validation</h2><p>' + (ctx.ai ? ('Final source: ' + esc(ctx.ai.output_source) + ' | Attempts: ' + ctx.ai.attempt + ' | Issues: ' + esc(ctx.ai.validation_issues_text || 'none') + ' | Warnings: ' + esc((ctx.ai.warnings || []).join('; ') || 'none')) : 'AI not executed.') + '</p>' +
    '<h2>Errors and failures</h2>' + (errors.length ? '<ul>' + errors.map(e => '<li>' + esc(e) + '</li>').join('') + '</ul>' : '<p>None recorded.</p>') +
    '<h2>Limitations</h2><ul><li>Passing these tests does not show that the system is bias-free or secure against all attacks.</li><li>Evidence status is taken from the dataset; no documents were independently verified.</li><li>No improvement over Workflow A is claimed until both workflows are run on identical inputs and their results compared.</li></ul></body></html>';
} catch (e) {
  errors.push('Report B generation failed: ' + e.message);
  html = '<!DOCTYPE html><html><body><h1>Responsible AI Testing Report - generation failed</h1><p>' + esc(e.message) + '</p></body></html>';
}
const val = ctx.validation || {};
const audit = {
  run_id: String(ctx.run_id), execution_timestamp: ctx.started_at || new Date().toISOString(), dataset_filename: ctx.dataset_filename || 'unknown',
  records_processed: val.rows_extracted || 0, ai_model: ctx.ai_model || '', final_route: ctx.route,
  data_validation_results: JSON.stringify({ valid: val.valid, critical_errors: val.critical_errors, missing_columns: val.missing_columns, missing_budget: (val.missing_budget || []).length, invalid_numeric: (val.invalid_numeric || []).length, zero_budget: (val.zero_budget || []).length, duplicate_ids: (val.duplicate_ids || []).length, calc_mismatches: val.calc_mismatch_count }),
  privacy_security_outcomes: JSON.stringify({ removed_fields: ctx.privacy ? ctx.privacy.removed_fields : [], redactions: ctx.privacy ? ctx.privacy.free_text_redactions : null, privacy_gate: ctx.privacy_gate ? { passed: ctx.privacy_gate.passed, exposures: ctx.privacy_gate.exposures } : null, injection_flagged_fields: ctx.injection ? ctx.injection.flagged_fields : null, injection_by_category: ctx.injection ? ctx.injection.by_category : null, ai_output_critical: ctx.ai ? ctx.ai.critical : null }),
  fairness_results: JSON.stringify(ctx.fairness ? { total_pairs: ctx.fairness.total_pairs, valid: ctx.fairness.valid_pairs, invalid: ctx.fairness.invalid_pairs, compared: ctx.fairness.pairs_compared, consistency_pct: ctx.fairness.ai_consistency_rate_pct, unexplained_ai_differences: ctx.fairness.ai_unexplained_differences.length, source_disparities: ctx.fairness.source_data_disparities.length } : { executed: false }),
  human_review_count: ctx.human_review_count || 0,
  tests_total: summary.total || 0, tests_passed: summary.passed || 0, tests_failed: summary.failed || 0, pass_percentage: summary.pass_percentage || 0,
  errors_and_failures: JSON.stringify(errors).slice(0, 4000)
};
return [{ json: { run_id: audit.run_id, route: ctx.route, dataset_filename: audit.dataset_filename, summary, audit, report_a_html: ctx.report_a_html, report_b_html: html, report_a_status: ctx.report_a_status } }];

// Package both reports and the audit record as downloadable files for the form completion page.
const d = $('Build Testing Report & Audit').first().json;
const stamp = String(d.run_id || 'run');
function file(content, name, mime) { return { data: Buffer.from(content, 'utf8').toString('base64'), mimeType: mime, fileName: name, fileExtension: name.split('.').pop() }; }
return [{ json: { run_id: d.run_id, route: d.route, summary: d.summary },
  binary: {
    report_a: file(d.report_a_html || '', 'Report_A_FPA_Management_Report_WorkflowB_' + stamp + '.html', 'text/html'),
    report_b: file(d.report_b_html || '', 'Report_B_Responsible_AI_Testing_Report_' + stamp + '.html', 'text/html'),
    audit_log: file(JSON.stringify(d.audit, null, 2), 'Audit_Log_WorkflowB_' + stamp + '.json', 'application/json')
  } }];
